window.__EXPERIENCE__=true;window.__STORY__={"storyId": "public-phone-demo-v3", "phoneVersion": 3, "title": "陌生人协议 · 手机演示", "owner": "雨昕", "date": "7月24日 星期五", "time": "22:05", "password": "420802", "quote": "有些话，留在手机里。", "wallpaper": "", "theme": "#6e8978", "names": {"chat": "微信", "album": "照片", "notes": "备忘录", "settings": "设置", "moments": "朋友圈", "ins": "ins", "redbook": "小红书", "phone": "电话", "sms": "信息", "music": "音乐", "calendar": "日历", "calculator": "计算器"}, "contacts": [{"id": "kun-fiction", "name": "KUN · 青菜小猪", "avatar": "", "templateId": "kun-fiction-v1", "messages": [{"id": "kun-msg-1", "date": "2023-06-29", "time": "07:16", "side": "them", "text": "起了吗。", "type": "text", "trigger": ""}, {"id": "kun-msg-2", "date": "2023-06-29", "time": "07:18", "side": "me", "text": "起了，准备开工。你怎么这么早？", "type": "text", "trigger": ""}, {"id": "kun-msg-3", "date": "2023-06-29", "time": "07:18", "side": "them", "text": "练完了。刚想把今日成果发给某位验收员。", "type": "text", "trigger": ""}, {"id": "kun-msg-4", "date": "2023-06-29", "time": "07:19", "side": "me", "text": "验收员忙着呢。", "type": "text", "trigger": ""}, {"id": "kun-msg-5", "date": "2023-06-29", "time": "07:19", "side": "them", "text": "好，青菜小猪先排队。", "type": "text", "trigger": ""}, {"id": "kun-msg-6", "date": "2023-06-29", "time": "11:46", "side": "them", "text": "［剧情红包 ¥200.00］\n别忘了吃午饭。", "type": "text", "trigger": ""}, {"id": "kun-msg-7", "date": "2023-06-29", "time": "11:47", "side": "me", "text": "你自己也吃。别又只有咖啡。", "type": "text", "trigger": ""}, {"id": "kun-msg-8", "date": "2023-06-29", "time": "11:48", "side": "them", "text": "收到。吃完给你交作业。", "type": "text", "trigger": ""}, {"id": "kun-msg-9", "date": "2023-06-29", "time": "12:23", "side": "them", "text": "雨昕，我们能见一面吗？", "type": "text", "trigger": ""}, {"id": "kun-msg-10", "date": "2023-06-29", "time": "12:25", "side": "me", "text": "坤，有些话不是见一面就能过去的。", "type": "text", "trigger": ""}, {"id": "kun-msg-11", "date": "2023-06-29", "time": "12:26", "side": "them", "text": "我知道。只是还有话没和你说清楚。", "type": "text", "trigger": ""}, {"id": "kun-msg-12", "date": "2023-06-29", "time": "12:28", "side": "me", "text": "我现在不想听解释。东西让雷坤来拿吧，我要出差。", "type": "text", "trigger": ""}, {"id": "kun-msg-13", "date": "2023-06-29", "time": "12:30", "side": "them", "text": "好。路上注意安全。", "type": "text", "trigger": ""}, {"id": "kun-msg-14", "date": "2025-05-22", "time": "19:02", "side": "me", "text": "给彼此留一点体面吧。我想让这些事慢慢离开我的生活。", "type": "text", "trigger": ""}, {"id": "kun-msg-15", "date": "2025-05-22", "time": "19:04", "side": "them", "text": "对不起。让你失望的部分，我不找借口。", "type": "text", "trigger": ""}, {"id": "kun-msg-16", "date": "2025-05-22", "time": "19:12", "side": "them", "text": "刚看到节目单上有你。准备得还顺利吗？", "type": "text", "trigger": ""}, {"id": "kun-msg-17", "date": "2025-05-22", "time": "19:14", "side": "me", "text": "你这样装没事，没有用。", "type": "text", "trigger": ""}, {"id": "kun-msg-18", "date": "2025-05-22", "time": "19:15", "side": "them", "text": "嗯。是我不知道该怎么往下说。", "type": "text", "trigger": ""}, {"id": "kun-msg-19", "date": "2025-05-22", "time": "19:19", "side": "them", "text": "洛杉矶那家烟熏三文鱼还在。", "type": "text", "trigger": ""}, {"id": "kun-msg-20", "date": "2025-05-22", "time": "19:20", "side": "me", "text": "你怎么总能绕回吃的。", "type": "text", "trigger": ""}, {"id": "kun-msg-21", "date": "2025-05-22", "time": "19:21", "side": "them", "text": "这个话题，没那么容易说错。", "type": "text", "trigger": ""}, {"id": "kun-msg-22", "date": "2025-05-22", "time": "19:24", "side": "me", "text": "我会提前过去。别想太多。", "type": "text", "trigger": ""}, {"id": "kun-msg-23", "date": "2025-05-22", "time": "19:24", "side": "them", "text": "好，只祝你演出顺利。", "type": "text", "trigger": ""}, {"id": "kun-msg-24", "date": "2026-05-11", "time": "16:03", "side": "them", "text": "听说深圳加场了。恭喜。", "type": "text", "trigger": ""}, {"id": "kun-msg-25", "date": "2026-05-11", "time": "16:05", "side": "me", "text": "谢谢。", "type": "text", "trigger": ""}, {"id": "kun-msg-26", "date": "2026-05-11", "time": "16:06", "side": "them", "text": "那我去听？", "type": "text", "trigger": ""}, {"id": "kun-msg-27", "date": "2026-05-11", "time": "16:08", "side": "me", "text": "别来了。被人看到，又要解释。", "type": "text", "trigger": ""}, {"id": "kun-msg-28", "date": "2026-05-11", "time": "16:10", "side": "them", "text": "嘉宾的位置也没有吗？", "type": "text", "trigger": ""}, {"id": "kun-msg-29", "date": "2026-05-11", "time": "16:11", "side": "me", "text": "这场不请嘉宾。", "type": "text", "trigger": ""}, {"id": "kun-msg-30", "date": "2026-05-11", "time": "16:12", "side": "them", "text": "好。", "type": "text", "trigger": ""}, {"id": "kun-msg-31", "date": "2026-05-11", "time": "16:16", "side": "them", "text": "有家鱼面店二十四小时营业。我刚才差点又拿它当借口。", "type": "text", "trigger": ""}, {"id": "kun-msg-32", "date": "2026-05-11", "time": "16:17", "side": "me", "text": "所以呢？", "type": "text", "trigger": ""}, {"id": "kun-msg-33", "date": "2026-05-11", "time": "16:18", "side": "them", "text": "所以不约了。你安心准备。", "type": "text", "trigger": ""}, {"id": "kun-msg-34", "date": "2026-05-22", "time": "23:06", "side": "them", "text": "顶流，今天辛苦。", "type": "text", "trigger": ""}, {"id": "kun-msg-35", "date": "2026-05-22", "time": "23:08", "side": "me", "text": "不敢不敢。你又要约饭？", "type": "text", "trigger": ""}, {"id": "kun-msg-36", "date": "2026-05-22", "time": "23:09", "side": "them", "text": "被你猜到了。", "type": "text", "trigger": ""}, {"id": "kun-msg-37", "date": "2026-05-22", "time": "23:11", "side": "me", "text": "我们不是吃饭的关系了。", "type": "text", "trigger": ""}, {"id": "kun-msg-38", "date": "2026-05-22", "time": "23:12", "side": "them", "text": "知道。", "type": "text", "trigger": ""}, {"id": "kun-msg-39", "date": "2026-05-22", "time": "23:15", "side": "me", "text": "放下吧，好吗。也放过你自己。", "type": "text", "trigger": ""}, {"id": "kun-msg-40", "date": "2026-05-22", "time": "23:18", "side": "them", "text": "我以前总想着，只要你回头，我就走那一百步。", "type": "text", "trigger": ""}, {"id": "kun-msg-41", "date": "2026-05-22", "time": "23:19", "side": "me", "text": "挺感人的。就是有点迟了。", "type": "text", "trigger": ""}, {"id": "kun-msg-42", "date": "2026-05-22", "time": "23:22", "side": "them", "text": "嗯。不能拿这句话，要求你等我。", "type": "text", "trigger": ""}, {"id": "kun-msg-43", "date": "2026-05-22", "time": "23:24", "side": "me", "text": "以后见到，就当陌生人吧。", "type": "text", "trigger": ""}, {"id": "kun-msg-44", "date": "2026-05-22", "time": "23:25", "side": "them", "text": "好。", "type": "text", "trigger": ""}, {"id": "kun-msg-45", "date": "2026-05-22", "time": "23:29", "side": "them", "text": "朋友也不能做了吗？", "type": "text", "trigger": ""}, {"id": "kun-msg-46", "date": "2026-05-22", "time": "23:31", "side": "me", "text": "不能。", "type": "text", "trigger": ""}, {"id": "kun-msg-47", "date": "2026-05-22", "time": "23:32", "side": "them", "text": "好。我记住了。", "type": "text", "trigger": ""}, {"id": "kun-msg-48", "date": "2026-07-24", "time": "21:07", "side": "me", "text": "蔡徐坤那条先别——", "type": "text", "trigger": ""}, {"id": "kun-msg-49", "date": "2026-07-24", "time": "21:07", "side": "me", "text": "发错了。", "type": "text", "trigger": ""}, {"id": "kun-msg-50", "date": "2026-07-24", "time": "21:08", "side": "them", "text": "我在。", "type": "text", "trigger": ""}, {"id": "kun-msg-51", "date": "2026-07-24", "time": "21:09", "side": "them", "text": "是在和别人提我的名字？不方便就不用答。", "type": "text", "trigger": ""}, {"id": "kun-msg-52", "date": "2026-07-24", "time": "21:11", "side": "me", "text": "你不是同意当陌生人了吗？", "type": "text", "trigger": ""}, {"id": "kun-msg-53", "date": "2026-07-24", "time": "21:12", "side": "them", "text": "同意了。", "type": "text", "trigger": ""}, {"id": "kun-msg-54", "date": "2026-07-24", "time": "21:13", "side": "them", "text": "可你发过来的消息，我还是不想敷衍。", "type": "text", "trigger": ""}, {"id": "kun-msg-55", "date": "2026-07-24", "time": "21:15", "side": "me", "text": "你现在倒是很会说。", "type": "text", "trigger": ""}, {"id": "kun-msg-56", "date": "2026-07-24", "time": "21:16", "side": "them", "text": "不是很会。刚才那句，改了两遍。", "type": "text", "trigger": ""}, {"id": "kun-msg-57", "date": "2026-07-24", "time": "23:48", "side": "me", "text": "你到新加坡了？", "type": "text", "trigger": ""}, {"id": "kun-msg-58", "date": "2026-07-24", "time": "23:49", "side": "them", "text": "到了。比你问的早一点。", "type": "text", "trigger": ""}, {"id": "kun-msg-59", "date": "2026-07-24", "time": "23:49", "side": "them", "text": "本来想说你都不关心我。", "type": "text", "trigger": ""}, {"id": "kun-msg-60", "date": "2026-07-24", "time": "23:50", "side": "them", "text": "算了，这句撤回。是我应该先说一声。", "type": "text", "trigger": ""}, {"id": "kun-msg-61", "date": "2026-07-24", "time": "23:51", "side": "me", "text": "咱俩又没什么关系。谁家分手还报备。", "type": "text", "trigger": ""}, {"id": "kun-msg-62", "date": "2026-07-24", "time": "23:52", "side": "them", "text": "嗯，不叫报备。", "type": "text", "trigger": ""}, {"id": "kun-msg-63", "date": "2026-07-24", "time": "23:53", "side": "them", "text": "就是想让你知道，平安到了。", "type": "text", "trigger": ""}], "options": [], "ai": {"enabled": false}}, {"id": "mom-fiction", "name": "妈妈", "templateId": "mom-fiction-v1", "avatar": "", "messages": [{"id": "mom-0", "side": "them", "text": "在忙吗？先别急着回，妈妈问件小事。", "date": "2026-07-24", "time": "18:03", "type": "text", "trigger": ""}, {"id": "mom-1", "side": "them", "text": "今天饭吃了吗？你那个护膝是不是又忘带了？", "date": "2026-07-24", "time": "18:03", "type": "text", "trigger": ""}, {"id": "mom-2", "side": "me", "text": "妈，吃过啦。护膝也戴了，给您检查。", "date": "2026-07-24", "time": "18:10", "type": "text", "trigger": ""}, {"id": "mom-3", "side": "them", "text": "谁要检查你。就是随口一问。", "date": "2026-07-24", "time": "18:11", "type": "text", "trigger": ""}, {"id": "mom-4", "side": "them", "text": "对了，你上次说楼下那家包子好吃，我今天买了。", "date": "2026-07-24", "time": "18:12", "type": "text", "trigger": ""}, {"id": "mom-5", "side": "me", "text": "您是不是又买多了？", "date": "2026-07-24", "time": "18:13", "type": "text", "trigger": ""}, {"id": "mom-6", "side": "them", "text": "没有，就两袋。", "date": "2026-07-24", "time": "18:14", "type": "text", "trigger": ""}, {"id": "mom-7", "side": "them", "text": "一袋给我，一袋给那个不知道什么时候回家的小孩。", "date": "2026-07-24", "time": "18:14", "type": "text", "trigger": ""}, {"id": "mom-8", "side": "me", "text": "那您帮小孩留着，小孩周末回去。谢谢妈妈。", "date": "2026-07-24", "time": "18:16", "type": "text", "trigger": ""}, {"id": "mom-9", "side": "them", "text": "听见了啊。可不是妈妈催你回来的。", "date": "2026-07-24", "time": "18:17", "type": "text", "trigger": ""}, {"id": "mom-10", "side": "me", "text": "您今天怎么这么开心？", "date": "2026-07-24", "time": "18:20", "type": "text", "trigger": ""}, {"id": "mom-11", "side": "them", "text": "我哪里开心了。", "date": "2026-07-24", "time": "18:21", "type": "text", "trigger": ""}, {"id": "mom-12", "side": "them", "text": "就是电视上刚好看见你。你那个转身，旁边邻居都说好看。", "date": "2026-07-24", "time": "18:21", "type": "text", "trigger": ""}, {"id": "mom-13", "side": "me", "text": "哎呀妈，您是不是又夸我了。", "date": "2026-07-24", "time": "18:22", "type": "text", "trigger": ""}, {"id": "mom-14", "side": "them", "text": "人家先夸的。我只是说，那是我闺女。", "date": "2026-07-24", "time": "18:23", "type": "text", "trigger": ""}, {"id": "mom-15", "side": "me", "text": "我得继续排练了，晚点给您打电话。", "date": "2026-07-24", "time": "18:25", "type": "text", "trigger": ""}, {"id": "mom-16", "side": "them", "text": "好好好，你忙。", "date": "2026-07-24", "time": "18:25", "type": "text", "trigger": ""}, {"id": "mom-17", "side": "them", "text": "水喝两口。汤给你留着，不催你。", "date": "2026-07-24", "time": "18:26", "type": "text", "trigger": ""}, {"id": "mom-18", "side": "me", "text": "妈，我到住的地方了。今天有一点累。", "date": "2026-07-24", "time": "22:01", "type": "text", "trigger": ""}, {"id": "mom-19", "side": "them", "text": "那就把肩膀放松一点，先坐会儿。", "date": "2026-07-24", "time": "22:02", "type": "text", "trigger": ""}, {"id": "mom-20", "side": "them", "text": "想聊天妈妈就陪你聊。不想聊，咱们明天再说也行。", "date": "2026-07-24", "time": "22:02", "type": "text", "trigger": ""}, {"id": "mom-21", "side": "me", "text": "您不用一直等我消息，早点睡。", "date": "2026-07-24", "time": "22:04", "type": "text", "trigger": ""}, {"id": "mom-22", "side": "them", "text": "我才没等呢，我电视剧还没看完。", "date": "2026-07-24", "time": "22:05", "type": "text", "trigger": ""}, {"id": "mom-23", "side": "them", "text": "就是想让你知道，什么时候想回家，家里都有饭。", "date": "2026-07-24", "time": "22:05", "type": "text", "trigger": ""}], "options": [], "ai": {"enabled": false}}], "photos": [{"id": "demo-photo-0", "title": "演示素材 · 晚霞", "src": "data:image/svg+xml;base64,", "time": "昨天"}, {"id": "demo-photo-1", "title": "演示素材 · 一日", "src": "data:image/svg+xml;base64,", "time": "昨天"}, {"id": "demo-photo-2", "title": "演示素材 · 排练", "src": "data:image/svg+xml;base64,", "time": "昨天"}, {"id": "demo-photo-3", "title": "演示素材 · 午后", "src": "data:image/svg+xml;base64,", "time": "昨天"}, {"id": "demo-photo-4", "title": "演示素材 · 回家", "src": "data:image/svg+xml;base64,", "time": "昨天"}, {"id": "demo-photo-5", "title": "演示素材 · 灯火", "src": "data:image/svg+xml;base64,", "time": "昨天"}], "notes": [{"id": "demo-note-1", "title": "给自己的一点提醒", "text": "关心不等于原谅。\n想说的话，等自己准备好了再说。", "time": "今天 21:30", "pinned": true}, {"id": "demo-note-2", "title": "周末回家", "text": "给妈妈带一束花。\n把护膝收进包里。\n有空就好好吃一顿饭。", "time": "昨天 18:20"}], "moments": [{"id": "demo-moment-1", "title": "妈妈", "author": "妈妈", "text": "今天汤煮多了一碗。\n谁要回家吃饭，自己说啊。", "time": "32分钟前", "images": ["data:image/svg+xml;base64,", "data:image/svg+xml;base64,", "data:image/svg+xml;base64,"], "likes": ["雨昕"], "comments": [{"author": "雨昕", "text": "周末就回来，谢谢妈妈。"}]}, {"id": "demo-moment-2", "title": "雨昕", "text": "把生活调回慢一点的速度。", "time": "昨天", "images": ["data:image/svg+xml;base64,"], "comments": []}], "ins": [{"id": "demo-ins", "title": "yuxin", "author": "yuxin", "text": "练习结束，给自己一点慢下来的时间。", "images": ["data:image/svg+xml;base64,", "data:image/svg+xml;base64,"], "time": "昨天", "comments": []}], "redbook": [{"id": "demo-red-1", "title": "排练包里的小清单", "author": "雨昕的日常", "text": "护膝、充电线、水杯。还有妈妈装进来的那一小袋零食。\n\n本条为虚构演示笔记。", "images": ["data:image/svg+xml;base64,"], "time": "今天", "comments": []}, {"id": "demo-red-2", "title": "下班之后，慢慢回家", "author": "日常记录", "text": "留一点时间给自己。", "images": ["data:image/svg+xml;base64,"], "time": "昨天", "comments": []}], "intro": {"enabled": true, "title": "捡到一部手机", "text": "向上滑动后，输入六位剧情密码 420802。\n\n这是界面演示：包含 KUN、妈妈和少量演示素材，不读取你的作者草稿。所有人物关系、日期与事件均为架空同人，与现实艺人及家庭无关。\n\n演示页不连接 AI；真实角色对话可使用你电脑上的 Ollama 本机版。", "button": "上滑，打开手机"}, "notification": {"app": "chat", "text": "妈妈：水喝两口，别的等你有空再说。", "contactId": "mom-fiction"}, "profiles": {"moments": {"name": "雨昕", "signature": "给生活留一点慢下来的时间。", "cover": "data:image/svg+xml;base64,"}}, "callRecords": [{"id": "demo-call", "name": "妈妈", "time": "今天 19:20", "kind": "missed"}], "sms": [{"id": "demo-sms", "name": "行程提醒", "messages": [{"id": "s1", "side": "them", "text": "演示提醒：你有一条待查看的行程备忘。", "time": "今天 18:10"}, {"id": "s2", "side": "me", "text": "收到，我晚点查看。", "time": "18:12"}]}], "tracks": [{"id": "demo-tone", "title": "晚安提示音（演示）", "artist": "本机演示音频", "cover": "data:image/svg+xml;base64,", "src": "data:audio/wav;base64,"}], "events": [{"id": "demo-event", "title": "回家吃饭", "date": "2026-07-24", "time": "19:00", "place": "故事里的家", "notes": "给妈妈带一束花。"}], "calendarDate": "2026-07-24"};
